-- Month Holiness completion: unify zamkovoi.yoga link colors (#0f3d2e).

update public.email_automation_steps set
  html_body = '<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-holiness/m7_email-c7a920a26246.png" alt="Месяц святости" width="504" height="159" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div>
<div style="margin:0px 0 0px;text-align:left;font-family:Arial,Helvetica,sans-serif;font-size:16px;line-height:1.55;"><p style="margin:0;padding:0;word-break:break-word;overflow-wrap:anywhere;word-break:break-word;overflow-wrap:anywhere;font-size:16px !important;line-height:24px;font-family:Arial,Helvetica,sans-serif;">Здравствуйте, {{name}}!</p><p style="margin:0;padding:0;line-height:1.55;height:1.55em;font-size:16px !important;font-family:Arial,Helvetica,sans-serif;">&nbsp;</p><p style="margin:0;padding:0;word-break:break-word;overflow-wrap:anywhere;word-break:break-word;overflow-wrap:anywhere;font-size:16px !important;line-height:24px;font-family:Arial,Helvetica,sans-serif;">Вот и завершился месяц практик, направленных на гармонизацию седьмой чакры. Я надеюсь, что этот месяц был для вас плодотворен, что вы почувствовали и улучшили состояние связи с Богом. Продолжайте практиковать и делать жизнь ещё лучше!</p><p style="margin:0;padding:0;line-height:1.55;height:1.55em;font-size:16px !important;font-family:Arial,Helvetica,sans-serif;">&nbsp;</p><p style="margin:0;padding:0;word-break:break-word;overflow-wrap:anywhere;word-break:break-word;overflow-wrap:anywhere;font-size:16px !important;line-height:24px;font-family:Arial,Helvetica,sans-serif;">И, так как месяц святости закончился, я предлагаю на волне благодарности отпустить все те обещания, которые в связи с этим практикумом вы могли давать мне или я мог давать вам. Они вас поддерживали, но более не нужны и свободны. Если какие-то обещания вы давали сами себе, но не выполнили (например, не практиковали в должной мере), предлагаю вам себя простить, и всё это также отпустить. Вы сделали лучшее, на что способны. Движемся дальше на легке :)</p><p style="margin:0;padding:0;line-height:1.55;height:1.55em;font-size:16px !important;font-family:Arial,Helvetica,sans-serif;">&nbsp;</p><p style="margin:0;padding:0;word-break:break-word;overflow-wrap:anywhere;word-break:break-word;overflow-wrap:anywhere;font-size:16px !important;line-height:24px;font-family:Arial,Helvetica,sans-serif;">Если вы ещё не записались на практики месяца "М+Ж", то я приглашаю вас сделать это прямо сейчас! Вас ожидает интереснейшая программа. Мы направим внимание на любовь. Но не в том глобальном космическом виде, с которым мы взаимодействовали в практикуме "Месяц любви", а именно в её мужско-женском проявлении. Тема актуальна практически для каждого, независимо от семейного статуса и возраста. Кому-то нужно гармонизировать настоящее, кому-то прошлое, кому-то и то и другое :) Чтобы ознакомиться с описанием этой программы и записаться, перейдите по ссылке - <a href="https://zamkovoi.yoga/mmz/" style="color:#0f3d2e;text-decoration:underline">https://zamkovoi.yoga/mmz/</a></p><p style="margin:0;padding:0;line-height:1.55;height:1.55em;font-size:16px !important;font-family:Arial,Helvetica,sans-serif;">&nbsp;</p><p style="margin:0;padding:0;word-break:break-word;overflow-wrap:anywhere;word-break:break-word;overflow-wrap:anywhere;font-size:16px !important;line-height:24px;font-family:Arial,Helvetica,sans-serif;">Хотя, я не удивлюсь, если вы предпочтёте углубиться в развитие седьмой чакры, и запишитесь на соответствующий интенсив или курс. Уж очень интересные плоды находятся на этом уровне :)<br>- Интенсив по 7 чакре: <a href="https://zamkovoi.yoga/i7/" style="color:#0f3d2e;text-decoration:underline">https://zamkovoi.yoga/i7/</a><br>- Курс "Путь души": <a href="https://zamkovoi.yoga/yogas/" style="color:#0f3d2e;text-decoration:underline">https://zamkovoi.yoga/yogas/</a></p><p style="margin:0;padding:0;line-height:1.55;height:1.55em;font-size:16px !important;font-family:Arial,Helvetica,sans-serif;">&nbsp;</p><p style="margin:0;padding:0;word-break:break-word;overflow-wrap:anywhere;word-break:break-word;overflow-wrap:anywhere;font-size:16px !important;line-height:24px;font-family:Arial,Helvetica,sans-serif;">А вообще, я подготовил всесторонний комплект практикумов, интенсивов и курсов, которые могут быть вам полезны. Чтобы выбрать то, что вам подойдёт, сначала вам нужно определиться с направлением - то есть честно осознать какая сфера жизни (или ситуации) сейчас вас более всего трогает (вызывает дискомфорт, или, наоборот, воодушевляет), а затем решить сколько времени вы готовы посвятить урокам и практикам. Ниже я перечислил практикумы и курсы, которые могут вас заинтересовать:</p><p style="margin:0;padding:0;line-height:1.55;height:1.55em;font-size:16px !important;font-family:Arial,Helvetica,sans-serif;">&nbsp;</p><p style="margin:0;padding:0;word-break:break-word;overflow-wrap:anywhere;word-break:break-word;overflow-wrap:anywhere;font-size:16px !important;line-height:24px;font-family:Arial,Helvetica,sans-serif;">ПРАКТИКУМЫ:<br>- Месяц здоровья: <a href="https://zamkovoi.yoga/m1" style="color:#0f3d2e;text-decoration:underline">https://zamkovoi.yoga/m1</a><br>- Месяц наслаждений: <a href="https://zamkovoi.yoga/m2" style="color:#0f3d2e;text-decoration:underline">https://zamkovoi.yoga/m2</a><br>- Месяц силы: <a href="https://zamkovoi.yoga/m3" style="color:#0f3d2e;text-decoration:underline">https://zamkovoi.yoga/m3</a><br>- Месяц любви: <a href="https://zamkovoi.yoga/m4" style="color:#0f3d2e;text-decoration:underline">https://zamkovoi.yoga/m4</a><br>- Месяц свободы: <a href="https://zamkovoi.yoga/m5" style="color:#0f3d2e;text-decoration:underline">https://zamkovoi.yoga/m5</a><br>- Месяц мудрости: <a href="https://zamkovoi.yoga/m6" style="color:#0f3d2e;text-decoration:underline">https://zamkovoi.yoga/m6</a><br>- Месяц святости: <a href="https://zamkovoi.yoga/m7" style="color:#0f3d2e;text-decoration:underline">https://zamkovoi.yoga/m7</a></p><p style="margin:0;padding:0;line-height:1.55;height:1.55em;font-size:16px !important;font-family:Arial,Helvetica,sans-serif;">&nbsp;</p><p style="margin:0;padding:0;word-break:break-word;overflow-wrap:anywhere;word-break:break-word;overflow-wrap:anywhere;font-size:16px !important;line-height:24px;font-family:Arial,Helvetica,sans-serif;">КУРСЫ:<br>- Йога и здоровье: <a href="https://zamkovoi.yoga/yoga1" style="color:#0f3d2e;text-decoration:underline">https://zamkovoi.yoga/yoga1</a><br>- Йога и женственность: <a href="https://zamkovoi.yoga/yoga2" style="color:#0f3d2e;text-decoration:underline">https://zamkovoi.yoga/yoga2</a><br>- Тантра - мистерия взаимоотношений: <a href="https://zamkovoi.yoga/tantra12" style="color:#0f3d2e;text-decoration:underline">https://zamkovoi.yoga/tantra12</a><br>- Осуществи мечту: <a href="https://zamkovoi.yoga/yoga3" style="color:#0f3d2e;text-decoration:underline">https://zamkovoi.yoga/yoga3</a><br>- Планета любви: <a href="https://zamkovoi.yoga/yoga4" style="color:#0f3d2e;text-decoration:underline">https://zamkovoi.yoga/yoga4</a><br>- Источник творческой силы: <a href="https://zamkovoi.yoga/yoga5" style="color:#0f3d2e;text-decoration:underline">https://zamkovoi.yoga/yoga5</a><br>- 36 шагов йоги: <a href="https://zamkovoi.yoga/yoga36" style="color:#0f3d2e;text-decoration:underline">https://zamkovoi.yoga/yoga36</a><br>- Путь души: <a href="https://zamkovoi.yoga/yogas" style="color:#0f3d2e;text-decoration:underline">https://zamkovoi.yoga/yogas</a></p><p style="margin:0;padding:0;line-height:1.55;height:1.55em;font-size:16px !important;font-family:Arial,Helvetica,sans-serif;">&nbsp;</p><p style="margin:0;padding:0;word-break:break-word;overflow-wrap:anywhere;word-break:break-word;overflow-wrap:anywhere;font-size:16px !important;line-height:24px;font-family:Arial,Helvetica,sans-serif;">Всех благ!<br>Сергей Замковой</p></div>',
  html_body_i18n = '{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-holiness/m7_email-c7a920a26246.png\" alt=\"Месяц святости\" width=\"504\" height=\"159\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Вот и завершился месяц практик, направленных на гармонизацию седьмой чакры. Я надеюсь, что этот месяц был для вас плодотворен, что вы почувствовали и улучшили состояние связи с Богом. Продолжайте практиковать и делать жизнь ещё лучше!</p><p></p><p>И, так как месяц святости закончился, я предлагаю на волне благодарности отпустить все те обещания, которые в связи с этим практикумом вы могли давать мне или я мог давать вам. Они вас поддерживали, но более не нужны и свободны. Если какие-то обещания вы давали сами себе, но не выполнили (например, не практиковали в должной мере), предлагаю вам себя простить, и всё это также отпустить. Вы сделали лучшее, на что способны. Движемся дальше на легке :)</p><p></p><p>Если вы ещё не записались на практики месяца &quot;М+Ж&quot;, то я приглашаю вас сделать это прямо сейчас! Вас ожидает интереснейшая программа. Мы направим внимание на любовь. Но не в том глобальном космическом виде, с которым мы взаимодействовали в практикуме &quot;Месяц любви&quot;, а именно в её мужско-женском проявлении. Тема актуальна практически для каждого, независимо от семейного статуса и возраста. Кому-то нужно гармонизировать настоящее, кому-то прошлое, кому-то и то и другое :) Чтобы ознакомиться с описанием этой программы и записаться, перейдите по ссылке - <a href=\"https://zamkovoi.yoga/mmz/\" style=\"color:#0f3d2e;text-decoration:underline\">https://zamkovoi.yoga/mmz/</a></p><p></p><p>Хотя, я не удивлюсь, если вы предпочтёте углубиться в развитие седьмой чакры, и запишитесь на соответствующий интенсив или курс. Уж очень интересные плоды находятся на этом уровне :)<br>- Интенсив по 7 чакре: <a href=\"https://zamkovoi.yoga/i7/\" style=\"color:#0f3d2e;text-decoration:underline\">https://zamkovoi.yoga/i7/</a><br>- Курс &quot;Путь души&quot;: <a href=\"https://zamkovoi.yoga/yogas/\" style=\"color:#0f3d2e;text-decoration:underline\">https://zamkovoi.yoga/yogas/</a></p><p></p><p>Всех благ!<br>Сергей Замковой</p>"}'::jsonb,
  blocks_i18n = '{"ru":[{"id":"course-month-holiness-header","alt":"Месяц святости","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-holiness/m7_email-c7a920a26246.png","type":"image","align":"center","width":"100%","marginTop":0,"marginBottom":24,"naturalWidth":533,"naturalHeight":168},{"id":"month-holiness-completion-text","html":"<p style=\"margin:0;padding:0;word-break:break-word;overflow-wrap:anywhere;font-size:16px !important;line-height:24px;font-family:Arial,Helvetica,sans-serif;\">Здравствуйте, {{name}}!</p><p style=\"margin:0;padding:0;line-height:1.55;height:1.55em;font-size:16px !important;font-family:Arial,Helvetica,sans-serif;\">&nbsp;</p><p style=\"margin:0;padding:0;word-break:break-word;overflow-wrap:anywhere;font-size:16px !important;line-height:24px;font-family:Arial,Helvetica,sans-serif;\">Вот и завершился месяц практик, направленных на гармонизацию седьмой чакры. Я надеюсь, что этот месяц был для вас плодотворен, что вы почувствовали и улучшили состояние связи с Богом. Продолжайте практиковать и делать жизнь ещё лучше!</p><p style=\"margin:0;padding:0;line-height:1.55;height:1.55em;font-size:16px !important;font-family:Arial,Helvetica,sans-serif;\">&nbsp;</p><p style=\"margin:0;padding:0;word-break:break-word;overflow-wrap:anywhere;font-size:16px !important;line-height:24px;font-family:Arial,Helvetica,sans-serif;\">И, так как месяц святости закончился, я предлагаю на волне благодарности отпустить все те обещания, которые в связи с этим практикумом вы могли давать мне или я мог давать вам. Они вас поддерживали, но более не нужны и свободны. Если какие-то обещания вы давали сами себе, но не выполнили (например, не практиковали в должной мере), предлагаю вам себя простить, и всё это также отпустить. Вы сделали лучшее, на что способны. Движемся дальше на легке :)</p><p style=\"margin:0;padding:0;line-height:1.55;height:1.55em;font-size:16px !important;font-family:Arial,Helvetica,sans-serif;\">&nbsp;</p><p style=\"margin:0;padding:0;word-break:break-word;overflow-wrap:anywhere;font-size:16px !important;line-height:24px;font-family:Arial,Helvetica,sans-serif;\">Если вы ещё не записались на практики месяца \"М+Ж\", то я приглашаю вас сделать это прямо сейчас! Вас ожидает интереснейшая программа. Мы направим внимание на любовь. Но не в том глобальном космическом виде, с которым мы взаимодействовали в практикуме \"Месяц любви\", а именно в её мужско-женском проявлении. Тема актуальна практически для каждого, независимо от семейного статуса и возраста. Кому-то нужно гармонизировать настоящее, кому-то прошлое, кому-то и то и другое :) Чтобы ознакомиться с описанием этой программы и записаться, перейдите по ссылке - <a href=\"https://zamkovoi.yoga/mmz/\" style=\"color:#0f3d2e;text-decoration:underline\">https://zamkovoi.yoga/mmz/</a></p><p style=\"margin:0;padding:0;line-height:1.55;height:1.55em;font-size:16px !important;font-family:Arial,Helvetica,sans-serif;\">&nbsp;</p><p style=\"margin:0;padding:0;word-break:break-word;overflow-wrap:anywhere;font-size:16px !important;line-height:24px;font-family:Arial,Helvetica,sans-serif;\">Хотя, я не удивлюсь, если вы предпочтёте углубиться в развитие седьмой чакры, и запишитесь на соответствующий интенсив или курс. Уж очень интересные плоды находятся на этом уровне :)<br>- Интенсив по 7 чакре: <a href=\"https://zamkovoi.yoga/i7/\" style=\"color:#0f3d2e;text-decoration:underline\">https://zamkovoi.yoga/i7/</a><br>- Курс \"Путь души\": <a href=\"https://zamkovoi.yoga/yogas/\" style=\"color:#0f3d2e;text-decoration:underline\">https://zamkovoi.yoga/yogas/</a></p><p style=\"margin:0;padding:0;line-height:1.55;height:1.55em;font-size:16px !important;font-family:Arial,Helvetica,sans-serif;\">&nbsp;</p><p style=\"margin:0;padding:0;word-break:break-word;overflow-wrap:anywhere;font-size:16px !important;line-height:24px;font-family:Arial,Helvetica,sans-serif;\">А вообще, я подготовил всесторонний комплект практикумов, интенсивов и курсов, которые могут быть вам полезны. Чтобы выбрать то, что вам подойдёт, сначала вам нужно определиться с направлением - то есть честно осознать какая сфера жизни (или ситуации) сейчас вас более всего трогает (вызывает дискомфорт, или, наоборот, воодушевляет), а затем решить сколько времени вы готовы посвятить урокам и практикам. Ниже я перечислил практикумы и курсы, которые могут вас заинтересовать:</p><p style=\"margin:0;padding:0;line-height:1.55;height:1.55em;font-size:16px !important;font-family:Arial,Helvetica,sans-serif;\">&nbsp;</p><p style=\"margin:0;padding:0;word-break:break-word;overflow-wrap:anywhere;font-size:16px !important;line-height:24px;font-family:Arial,Helvetica,sans-serif;\">ПРАКТИКУМЫ:<br>- Месяц здоровья: <a href=\"https://zamkovoi.yoga/m1\" style=\"color:#0f3d2e;text-decoration:underline\">https://zamkovoi.yoga/m1</a><br>- Месяц наслаждений: <a href=\"https://zamkovoi.yoga/m2\" style=\"color:#0f3d2e;text-decoration:underline\">https://zamkovoi.yoga/m2</a><br>- Месяц силы: <a href=\"https://zamkovoi.yoga/m3\" style=\"color:#0f3d2e;text-decoration:underline\">https://zamkovoi.yoga/m3</a><br>- Месяц любви: <a href=\"https://zamkovoi.yoga/m4\" style=\"color:#0f3d2e;text-decoration:underline\">https://zamkovoi.yoga/m4</a><br>- Месяц свободы: <a href=\"https://zamkovoi.yoga/m5\" style=\"color:#0f3d2e;text-decoration:underline\">https://zamkovoi.yoga/m5</a><br>- Месяц мудрости: <a href=\"https://zamkovoi.yoga/m6\" style=\"color:#0f3d2e;text-decoration:underline\">https://zamkovoi.yoga/m6</a><br>- Месяц святости: <a href=\"https://zamkovoi.yoga/m7\" style=\"color:#0f3d2e;text-decoration:underline\">https://zamkovoi.yoga/m7</a></p><p style=\"margin:0;padding:0;line-height:1.55;height:1.55em;font-size:16px !important;font-family:Arial,Helvetica,sans-serif;\">&nbsp;</p><p style=\"margin:0;padding:0;word-break:break-word;overflow-wrap:anywhere;font-size:16px !important;line-height:24px;font-family:Arial,Helvetica,sans-serif;\">КУРСЫ:<br>- Йога и здоровье: <a href=\"https://zamkovoi.yoga/yoga1\" style=\"color:#0f3d2e;text-decoration:underline\">https://zamkovoi.yoga/yoga1</a><br>- Йога и женственность: <a href=\"https://zamkovoi.yoga/yoga2\" style=\"color:#0f3d2e;text-decoration:underline\">https://zamkovoi.yoga/yoga2</a><br>- Тантра - мистерия взаимоотношений: <a href=\"https://zamkovoi.yoga/tantra12\" style=\"color:#0f3d2e;text-decoration:underline\">https://zamkovoi.yoga/tantra12</a><br>- Осуществи мечту: <a href=\"https://zamkovoi.yoga/yoga3\" style=\"color:#0f3d2e;text-decoration:underline\">https://zamkovoi.yoga/yoga3</a><br>- Планета любви: <a href=\"https://zamkovoi.yoga/yoga4\" style=\"color:#0f3d2e;text-decoration:underline\">https://zamkovoi.yoga/yoga4</a><br>- Источник творческой силы: <a href=\"https://zamkovoi.yoga/yoga5\" style=\"color:#0f3d2e;text-decoration:underline\">https://zamkovoi.yoga/yoga5</a><br>- 36 шагов йоги: <a href=\"https://zamkovoi.yoga/yoga36\" style=\"color:#0f3d2e;text-decoration:underline\">https://zamkovoi.yoga/yoga36</a><br>- Путь души: <a href=\"https://zamkovoi.yoga/yogas\" style=\"color:#0f3d2e;text-decoration:underline\">https://zamkovoi.yoga/yogas</a></p><p style=\"margin:0;padding:0;line-height:1.55;height:1.55em;font-size:16px !important;font-family:Arial,Helvetica,sans-serif;\">&nbsp;</p><p style=\"margin:0;padding:0;word-break:break-word;overflow-wrap:anywhere;font-size:16px !important;line-height:24px;font-family:Arial,Helvetica,sans-serif;\">Всех благ!<br>Сергей Замковой</p>","type":"text","align":"left","fontSize":"md","marginTop":0,"fontFamily":"system","marginBottom":0}]}'::jsonb
